prog='''def transform(grid):
    from collections import deque
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if g[r][c] not in (0, 1) or (r, c) in seen:
                continue
            comp, stack = [], [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        yy, xx = y + dy, x + dx
                        if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and g[yy][xx] in (0, 1):
                            seen.add((yy, xx)); stack.append((yy, xx))
            blues = [y for y, x in comp if g[y][x] == 1]
            if blues:
                cutoff = max(blues)
                for y, x in comp:
                    if g[y][x] == 0 and y > cutoff:
                        g[y][x] = 5
    for r in range(h):
        for c in range(w):
            if g[r][c] in (2, 9):
                g[r][c] = 3
    return g
'''
